using Avalonia.Controls;using SalekhPos.Desktop.Application.Management;namespace SalekhPos.Desktop;public sealed partial class ManagerSubscriptionsWindow:Window{private readonly ISubscriptionManager manager;private readonly Guid organizationId;public ManagerSubscriptionsWindow()=>throw new InvalidOperationException("Subscription runtime is required.");public ManagerSubscriptionsWindow(ISubscriptionManager manager,Guid organizationId){this.manager=manager??throw new ArgumentNullException(nameof(manager));if(organizationId==Guid.Empty)throw new ArgumentException("Organization is required.");this.organizationId=organizationId;InitializeComponent();ScopeText.Text=$"Organization {organizationId:D}";Opened+=async(_,_)=>await Refresh();}private async void RefreshClick(object? s,Avalonia.Interactivity.RoutedEventArgs e)=>await Refresh();private async void LoadClick(object? s,Avalonia.Interactivity.RoutedEventArgs e)=>await Execute(async()=>{var id=Guid.Parse(SubscriptionBox.Text??"");var sub=await manager.GetAsync(organizationId,id,default);var ent=await manager.EntitlementsAsync(organizationId,id,default);SubscriptionText.Text=$"{sub.Status} · {sub.PeriodStart:u} → {sub.PeriodEnd:u} · cancel at end: {sub.CancelAtPeriodEnd}";EntitlementList.ItemsSource=ent.Limits.OrderBy(x=>x.Key).Select(x=>$"{x.Key}: {x.Value}").ToArray();});private async Task Refresh()=>await Execute(async()=>{var p=await manager.PlansAsync(organizationId,default);PlanList.ItemsSource=p.Select(x=>$"{x.Name} · {x.Price:0.00} {x.Currency}/{x.Interval} · {string.Join(", ",x.Entitlements.Select(e=>$"{e.Key}={e.Value}"))}").ToArray();});private async Task Execute(Func<Task>a){try{await a();MessageText.Text="";}catch(Exception ex)when(ex is ArgumentException or InvalidOperationException or HttpRequestException or FormatException){MessageText.Text=ex is HttpRequestException?"Subscription service request failed.":ex.Message;}}}